local function X(a,b)
  if bit32 and bit32.bxor then return bit32.bxor(a,b) end
  if bit and bit.bxor then return bit.bxor(a,b) end
  local r,p=0,1
  a,b=math.floor(a),math.floor(b)
  while a>0 or b>0 do
    local aa,bb=a%2,b%2
    if aa~=bb then r=r+p end
    a,b,p=(a-aa)/2,(b-bb)/2,p*2
  end
  return r
end
local function D(data)
  if crypt and crypt.base64decode then
    local ok,r=pcall(crypt.base64decode,data)
    if ok and type(r)=="string" and #r>0 then return r end
  end
  if syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then
    local ok,r=pcall(syn.crypt.base64.decode,data)
    if ok and type(r)=="string" and #r>0 then return r end
  end
  local abc="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  data=string.gsub(data,"[^A-Za-z0-9+/=]","")
  local t,n={},0
  local function push(c) n=n+1 t[n]=string.char(c) end
  for i=1,#data,4 do
    local a=string.find(abc,string.sub(data,i,i),1,true)
    local b=string.find(abc,string.sub(data,i+1,i+1),1,true)
    if not a or not b then break end
    a,b=a-1,b-1
    push(a*4+math.floor(b/16))
    local cch=string.sub(data,i+2,i+2)
    if cch~="=" then
      local c=string.find(abc,cch,1,true)
      if c then
        c=c-1
        push((b%16)*16+math.floor(c/4))
        local dch=string.sub(data,i+3,i+3)
        if dch~="=" then
          local d=string.find(abc,dch,1,true)
          if d then push((c%4)*64+(d-1)) end
        end
      end
    end
  end
  return table.concat(t)
end
local function fail(err)
  pcall(function()
    local pl=game:GetService("Players").LocalPlayer or game:GetService("Players").PlayerAdded:Wait()
    local g=Instance.new("ScreenGui")
    g.Name="BuffToolsLoadFail"
    g.ResetOnSpawn=false
    g.IgnoreGuiInset=true
    g.Parent=pl:WaitForChild("PlayerGui")
    local tb=Instance.new("TextBox")
    tb.Size=UDim2.new(0.7,0,0.28,0)
    tb.Position=UDim2.new(0.15,0,0.1,0)
    tb.BackgroundColor3=Color3.fromRGB(20,4,8)
    tb.TextColor3=Color3.fromRGB(255,220,220)
    tb.Text="BuffTools load fail:\n"..tostring(err)
    tb.TextWrapped=true
    tb.ClearTextOnFocus=false
    tb.MultiLine=true
    tb.TextSize=16
    tb.Font=Enum.Font.Code
    tb.Parent=g
  end)
end
local ok,err=pcall(function()
  local raw=D(C)
  local o,kn={},#_s
  for i=1,#raw do
    o[i]=string.char(X(string.byte(raw,i),string.byte(_s,(i-1)%kn+1)))
  end
  local src=table.concat(o)
  local fn,e=loadstring(src)
  if not fn and type(load)=="function" then fn,e=load(src) end
  if not fn then error(tostring(e)) end
  fn()
end)
if not ok then fail(err) end
